fn NP6_claims_canonical_contents() {
 let mut framed=[0u8;3717];
 for v in 0..87 {
  for l in 0..4 {
   let word=kani::any::<u32>()%P;
   let bytes=word.to_le_bytes();
   for b in 0..4 {framed[5+v*32+l*4+b]=bytes[b];}
  }
 }
 let root=[0u8;32];
 let prefix=r1_wire::np6_prefix(&root,&framed);
 let a=shipped::call(&prefix);
 let b=reference::call(&prefix);
 assert!(a.is_ok());assert!(b.is_ok());
 if let (Ok(a),Ok(b))=(a,b) {
  let i=(kani::any::<u8>()%3) as usize;let j=(kani::any::<u8>()%29) as usize;
  assert!(a[i][j]==b[i][j]);
 }
}

fn NP6_owned_transfers_and_layout(){
 assert!(size_of::<M31>()==4);assert!(size_of::<CM31>()==8);assert!(size_of::<QM31>()==16);
 assert!(size_of::<Row>()==464);assert!(size_of::<Claims>()==1392);assert!(align_of::<Claims>()==4);
 assert!(!needs_drop::<Claims>());assert!(!needs_drop::<MaybeUninit<Claims>>());
 let nl=Layout::array::<MaybeUninit<Claims>>(1).unwrap();
 let rl=Layout::array::<Row>(3).unwrap();
 assert!(nl.size()==rl.size());assert!(nl.align()==rl.align());
 let mut raw=Vec::<MaybeUninit<Claims>>::new();raw.try_reserve_exact(1).unwrap();assert!(raw.capacity()==1);
 let rows=[row(kani::any()),row(kani::any()),row(kani::any())];
 let mut native=aspis_core::r0::heap::uninit::<Claims>().unwrap();
 let original=native.as_mut_ptr();
 for p in 0..3 {unsafe{native.as_mut_ptr().cast::<Row>().add(p).write(rows[p]);}}
 let native=unsafe{native.assume_init()};assert!(core::ptr::eq(original,&*native));
 let values=aspis_core::r0::heap::filled(3,[QM31::ZERO;29]).unwrap();assert!(values.capacity()==3);
 let original=values.as_ptr();let slice=values.into_boxed_slice();assert!(core::ptr::eq(original,slice.as_ptr()));
 let owned:Box<Claims>=slice.try_into().unwrap();assert!(core::ptr::eq(original,owned.as_ptr()));
 let i=(kani::any::<u8>()as usize)%3;let j=(kani::any::<u8>()as usize)%29;
 assert!(native[i][j]==rows[i][j]);assert!(owned[i][j]==QM31::ZERO);
}

fn NP6_static_length_rejection(){
 let framed:[u8;932]=kani::any();
 let root=[0u8;32];
 let prefix=r1_wire::np6_prefix(&root,&framed);
 let a=shipped::call(&prefix);let b=reference::call(&prefix);
 match a {Err(e)=>assert!(e==r1_wire::Error::Length{row:25}),Ok(_)=>assert!(false)}
 match b {Err(e)=>assert!(e==r1_wire::Error::Length{row:25}),Ok(_)=>assert!(false)}
}

fn NP6_construct_all_errors(){
 let rows=[row(kani::any()),row(kani::any()),row(kani::any())];
 let failure=kani::any::<u8>();
 let error=match kani::any::<u8>()%11 {
 0=>Error::Allocation,1=>Error::RowOrder{expected:kani::any(),actual:kani::any()},2=>Error::InvalidRow,
 3=>Error::Tag{row:kani::any()},4=>Error::Length{row:kani::any()},5=>Error::NonCanonical{row:kani::any(),value:kani::any()},
 6=>Error::Boundary{round:kani::any()},7=>Error::Terminal,8=>Error::EqualCirclePoints,9=>Error::TrailingBytes,_=>Error::Public};
 let a=native(rows,failure,error);
 let b=owned(rows,failure,error);
 match (a,b){
  (Ok(a),Ok(b))=>{let i=(kani::any::<u8>()%3) as usize;let j=(kani::any::<u8>()%29) as usize;assert_eq!(a[i][j],b[i][j]);kani::cover!(true,"native initialized box returns arbitrary contents");},
  (Err(a),Err(b))=>{assert_eq!(a,b);kani::cover!(failure==2,"third decode error drops partial native allocation");},
  _=>panic!("construction Result mismatch"),
 }
}

fn NP6_complete_result() {
 let framed: [u8;3717] = kani::any();
 let root=[0u8;32];
 let prefix=r1_wire::np6_prefix(&root,&framed);
 let native=shipped::call(&prefix);
 let owned=reference::call(&prefix);
 assert!(native.is_ok()==owned.is_ok());
 if let (Err(a),Err(b))=(native,owned) {assert!(a==b);}
}

fn NP6_uninit_allocation_outcomes(){
 let result=aspis_core::r0::heap::uninit::<Claims>();
 kani::cover!(result.is_ok(),"native helper returns an owned MaybeUninit box");
 kani::cover!(matches!(result,Err(aspis_core::r0::Error::Allocation)),"native helper propagates allocation failure");
}

fn NP6_filled_allocation_outcomes(){
 let result=aspis_core::r0::heap::filled(3,[QM31::ZERO;29]);
 kani::cover!(result.is_ok(),"safe helper returns three initialized rows");
 kani::cover!(matches!(result,Err(aspis_core::r0::Error::Allocation)),"safe helper propagates allocation failure");
}
